css
/* ♡ Pink Sugar Hearts — MyEdSpace */

:root {
  /* swap these colours if you want */
  --my-pink: #ff9fc8;
  --my-hot-pink: #f47eaf;
  --my-blush: #fff0f6;
  --my-cream: #fffafd;
  --my-text: #80556b;
  --my-border: #ffd0e3;
}

/* dreamy pink background */
body {
  background-color: var(--my-blush) !important;
  background-image:
    radial-gradient(circle at 12px 12px, #ffb6d5 2px, transparent 3px),
    radial-gradient(circle at 36px 36px, #ffd1e4 2px, transparent 3px) !important;
  background-size: 48px 48px !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* pretty headings */
h1, h2, h3 {
  color: #e77eaa !important;
  letter-spacing: 0.5px !important;
}

/* cute links */
a {
  color: #e77eaa !important;
  text-decoration-color: #ffb4d2 !important;
}

/* soft rounded images */
img {
  border-radius: 14px !important;
}

/* sweet selection colour */
::selection {
  background: #ffb6d5 !important;
  color: white !important;
}

/* pastel scrollbars */
::-webkit-scrollbar {
  width: 10px !important;
}

::-webkit-scrollbar-thumb {
  background: #ffb1d0 !important;
  border-radius: 20px !important;
  border: 2px solid #fff0f6 !important;
}

::-webkit-scrollbar-track {
  background: #fff0f6 !important;
}
